contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take an artId and an amount of ETH to send when calling createArtFromFactory.
    // The rule: after a non-reverting call, tokenIdCounter increases by 1 and protocolFeeDestination
    // receives (or c forwarded) at least phiFactory.artCreateFee() (observed through protocolFeeDestination getter
    // on the factory via c.getPhiFactoryContract().protocolFeeDestination() and artCreateFee()).
    function run(uint256 artId, uint256 sendAmount) public payable {
        // require we have enough balance to send the requested ETH to c
        require(address(this).balance >= sendAmount, "insufficient balance for test");

        // Read pre-state observable: tokenIdCounter and c balance
        uint256 beforeCounter = c.tokenIdCounter();
        uint256 beforeCBalance = address(c).balance;

        // Determine expected art fee using phiFactory via c.getPhiFactoryContract()
        IPhiFactory factory = c.getPhiFactoryContract();
        uint256 artFee = factory.artCreateFee();
        address protocolDest = factory.protocolFeeDestination();

        bool reverted;
        uint256 createdTokenId;

        // Perform the state-changing call; capture revert
        try c.createArtFromFactory{ value: sendAmount }(artId) returns (uint256 tokenId) {
            reverted = false;
            createdTokenId = tokenId;
        } catch {
            reverted = true;
        }

        // Observables after call
        uint256 afterCounter = c.tokenIdCounter();
        uint256 afterCBalance = address(c).balance;

        // If the call didn't revert, then tokenIdCounter must have incremented by 1
        // and the contract's balance must have decreased by at least artFee (since it forwards artFee to protocolFeeDestination).
        // If it reverted, we impose no further requirement.
        if (!reverted) {
            assert(afterCounter == beforeCounter + 1 && beforeCBalance >= afterCBalance && (beforeCBalance - afterCBalance) >= artFee);
        } else {
            // In the reverted case, assert that counter didn't change (revert implies no state changes in c)
            assert(afterCounter == beforeCounter);
        }
    }

    receive() external payable {}
}

