contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Run a single call that sends `value` wei to createArtFromFactory(artId_)
    // We observe: (1) the returned tokenId equals the previous tokenIdCounter,
    // (2) after the call, tokenIdCounter increased by 1,
    // (3) the protocolFeeDestination's balance increased by exactly artCreateFee,
    // where artCreateFee is read from the factory via c.phiFactoryContract().artCreateFee().
    function run(uint256 artId_, uint256 value, address payable dummy) public payable {
        // we will forward `value` wei to c; ensure this contract has enough
        require(address(this).balance >= value, "not enough balance");

        // read observables before
        uint256 beforeCounter = c.tokenIdCounter();
        address factory = address(c.phiFactoryContract());
        // get art create fee from factory (public view through phiFactoryContract)
        uint256 artFee;
        try c.phiFactoryContract().artCreateFee() returns (uint256 f) {
            artFee = f;
        } catch {
            // If the factory call reverts, set artFee to 0 to still allow testing behavior
            artFee = 0;
        }

        // read protocol destination before
        address protoDest = c.protocolFeeDestination();
        uint256 beforeProtoBal = protoDest.balance;

        bool reverted = false;
        uint256 returnedTokenId = 0;
        // calling the state-changing function as top-level statement
        try c.createArtFromFactory{value: value}(artId_) returns (uint256 tid) {
            returnedTokenId = tid;
        } catch {
            reverted = true;
        }

        // read observables after
        uint256 afterCounter = c.tokenIdCounter();
        uint256 afterProtoBal = protoDest.balance;

        // General rule (assert): If the call did not revert then
        //  - returned token id equals the before counter,
        //  - tokenIdCounter increased by exactly 1,
        //  - protocolFeeDestination's balance increased by artFee (but not more).
        // If the call reverted then no guarantees are made here.
        assert(reverted || (
            returnedTokenId == beforeCounter
            && afterCounter == beforeCounter + 1
            && afterProtoBal - beforeProtoBal == artFee
        ));
    }

    // allow receiving ether for funding this test
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We call claimFromFactory on c (a state-changing call) with parameters
    // and assert that if it does not revert then the recipient's balance and totalSupply
    // for the mapped token id both increased by the requested quantity.
    function run(
        uint256 artId_,
        address minter_,
        address ref_,
        address verifier_,
        uint256 quantity_,
        bytes32 data_,
        string calldata imageURI_,
        uint256 value
    ) public payable {
        // ensure this test contract has the Ether to forward if needed
        require(address(this).balance >= value, "insufficient balance");

        // Observe before-values via public getters
        uint256 tokenId = c.getTokenIdFromFactoryArtId(artId_);
        // If tokenId is zero, contract would revert InValdidTokenId(); still we allow trying
        uint256 beforeBalance = c.balanceOf(minter_, tokenId);
        uint256 beforeTotal = c.totalSupply(tokenId);

        bool reverted;
        // top-level state-changing call as required
        try c.claimFromFactory{value: value}(artId_, minter_, ref_, verifier_, quantity_, data_, imageURI_) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterBalance = c.balanceOf(minter_, tokenId);
        uint256 afterTotal = c.totalSupply(tokenId);

        // General rule: if the call didn't revert then both the recipient balance and totalSupply
        // increased by exactly the quantity requested. If it reverted, no guarantee.
        assert(reverted || (afterBalance == beforeBalance + quantity_ && afterTotal == beforeTotal + quantity_));
    }

    receive() external payable {}
}

contract InvMutTest {
