    // We test that a successful createArtFromFactory call increments tokenIdCounter by 1
    // and returns the created token id equal to the old counter value.
    function run(uint256 artId_, uint256 value) public payable {
        // This contract was deployed as the phiFactory in C's initialize in the harness.
        // Ensure we have funds to forward if needed.
        require(address(this).balance >= value, "insufficient balance");

        // Observe tokenIdCounter before the call
        uint256 beforeCounter = c.tokenIdCounter();

        bool reverted;
        uint256 returnedTokenId = type(uint256).max;

        // Top-level state-changing call. We call as this contract (which is supposed to be the phiFactory).
        try c.createArtFromFactory{ value: value }(artId_) returns (uint256 tokenId) {
            reverted = false;
            returnedTokenId = tokenId;
        } catch {
            reverted = true;
        }

        // Observe tokenIdCounter after the call
        uint256 afterCounter = c.tokenIdCounter();

        // General rule: if the call succeeded (did not revert) then afterCounter == beforeCounter + 1
        // and the returned tokenId equals the prior beforeCounter value.
        assert(reverted || (afterCounter == beforeCounter + 1 && returnedTokenId == beforeCounter));
    }

    receive() external payable {}
}
